/**
 * Command headers, generated by the client and validated by the API.
 *
 * Every command in this contract carries two identifiers that are not the same
 * thing. `Idempotency-Key` is HTTP replay: resending it with the same body
 * returns the stored result instead of acting twice. `Command-Id` is the
 * identity of the row the command creates, which is why it must be a UUIDv7 —
 * the format embeds a timestamp, and the database orders evidence and claims by
 * it as a tiebreaker. Generating one early, before the person acted, would stamp
 * it with the wrong moment.
 *
 * This lives in the contract package because both `apps/space` and
 * `apps/studio-web` need it and an app may never import another app. The formats
 * are dictated by the contract itself — the API rejects anything its UUID
 * patterns do not match — so this was never application code.
 *
 * Randomness and the clock arrive as arguments rather than being read here. The
 * two runtimes disagree about where randomness comes from (`crypto` on the web,
 * `expo-crypto` on Hermes) and a function that reached for either would be
 * untestable in the other.
 */

const UUID_BYTES = 16

/** Source of cryptographic randomness, supplied by each runtime. */
export interface CommandRandomness {
  randomBytes(length: number): Uint8Array
}

export interface CommandHeaders {
  idempotencyKey: string
  commandId: string
}

export function newCommand(random: CommandRandomness, now: number): CommandHeaders {
  return {
    idempotencyKey: uuidV4(random.randomBytes(UUID_BYTES)),
    commandId: uuidV7(random.randomBytes(UUID_BYTES), now),
  }
}

export function uuidV4(bytes: Uint8Array): string {
  const value = stamped(bytes, 0x40)
  return format(value)
}

/** Milliseconds go big-endian into the first six bytes, so ids sort by time. */
export function uuidV7(bytes: Uint8Array, timestamp: number): string {
  const value = stamped(bytes, 0x70)
  let remaining = Math.floor(timestamp)
  for (let index = 5; index >= 0; index -= 1) {
    value[index] = remaining & 0xff
    remaining = Math.floor(remaining / 256)
  }
  return format(value)
}

/** Short input would produce an id the API rejects, so it throws here instead. */
function stamped(bytes: Uint8Array, version: number): Uint8Array {
  if (bytes.length < UUID_BYTES) {
    throw new RangeError(`a UUID needs ${UUID_BYTES} bytes, received ${bytes.length}`)
  }
  const value = Uint8Array.from(bytes.subarray(0, UUID_BYTES))
  value[6] = ((value[6] ?? 0) & 0x0f) | version
  value[8] = ((value[8] ?? 0) & 0x3f) | 0x80
  return value
}

function format(value: Uint8Array): string {
  const hex = Array.from(value, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20, 32),
  ].join('-')
}
